<?php
// ================= MODUL DATA ANTREAN =================
// Menampilkan daftar antrean Admin dengan pencarian, filter, dan pagination.
declare(strict_types=1);require_once __DIR__.'/../includes/middleware_peran.php';require_once __DIR__.'/../konfigurasi/koneksi_database.php';wajib_peran('admin');
$cari=trim((string)($_GET['cari']??''));$status=(string)($_GET['status']??'');$halaman=max(1,(int)($_GET['halaman']??1));$batas=10;$syarat=[];$parameter=[];
if($cari!==''){$syarat[]='(pa.nama_pasien LIKE :nama OR po.kode_poli LIKE :kode OR CAST(a.nomor_antrean AS CHAR) LIKE :nomor)';$parameter=['nama'=>"%$cari%",'kode'=>"%$cari%",'nomor'=>"%$cari%"];}if(in_array($status,['menunggu','dipanggil','selesai','dibatalkan'],true)){$syarat[]='a.status_antrean=:status';$parameter['status']=$status;}$where=$syarat?' WHERE '.implode(' AND ',$syarat):'';$dasar=' FROM antrean a INNER JOIN pasien pa ON pa.id_pasien=a.id_pasien INNER JOIN poli po ON po.id_poli=a.id_poli';
$q=$koneksi_database->prepare('SELECT COUNT(*)'.$dasar.$where);$q->execute($parameter);$total=(int)$q->fetchColumn();$total_halaman=max(1,(int)ceil($total/$batas));$halaman=min($halaman,$total_halaman);$offset=($halaman-1)*$batas;$q=$koneksi_database->prepare('SELECT a.id_antrean,a.nomor_antrean,a.tanggal_antrean,a.status_antrean,pa.nama_pasien,po.kode_poli,po.nama_poli'.$dasar.$where.' ORDER BY a.tanggal_antrean DESC,a.nomor_antrean ASC LIMIT :batas OFFSET :offset');foreach($parameter as $nama=>$nilai)$q->bindValue(':'.$nama,$nilai,PDO::PARAM_STR);$q->bindValue(':batas',$batas,PDO::PARAM_INT);$q->bindValue(':offset',$offset,PDO::PARAM_INT);$q->execute();$data=$q->fetchAll();
function url_antrean(int $halaman,string $cari,string $status):string{return url_aplikasi('admin/data-antrean.php?'.http_build_query(array_filter(['halaman'=>$halaman,'cari'=>$cari,'status'=>$status])));}
$judul_halaman='Data Antrean';$stylesheet_tambahan='assets/css/gaya-dashboard.css';$menu_aktif='antrean';require_once __DIR__.'/../includes/kepala.php';require_once __DIR__.'/../includes/navbar_admin.php';?>
<div class="d-flex dashboard-layout halaman-dashboard"><?php require_once __DIR__.'/../includes/sidebar_admin.php';?><main class="flex-grow-1 p-3 p-md-4 p-xl-5 overflow-hidden"><div class="d-flex justify-content-between align-items-md-center flex-column flex-md-row gap-3 mb-4"><div><p class="teks-label mb-1">Manajemen Data</p><h1 class="h3 mb-0">Data Antrean</h1></div><a class="btn btn-success align-self-start" href="<?=aman_html(url_aplikasi('admin/formulir-antrean.php'));?>">+ Tambah Antrean</a></div><?php require_once __DIR__.'/../includes/notifikasi.php';?>
<form class="card kartu-dashboard p-3 mb-4"><div class="row g-2"><div class="col-md"><input class="form-control" name="cari" value="<?=aman_html($cari);?>" placeholder="Nama pasien, nomor, atau kode poli"></div><div class="col-md-3"><select class="form-select" name="status"><option value="">Semua status</option><?php foreach(['menunggu','dipanggil','selesai','dibatalkan'] as $s):?><option value="<?=$s;?>" <?=$status===$s?'selected':'';?>><?=ucfirst($s);?></option><?php endforeach;?></select></div><div class="col-auto"><button class="btn btn-success">Cari</button></div></div></form>
<section class="card kartu-dashboard"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead class="table-success"><tr><th class="ps-3">Nomor</th><th>Pasien</th><th>Poli</th><th>Tanggal</th><th>Status</th><th class="text-end pe-3">Aksi</th></tr></thead><tbody><?php if(!$data):?><tr><td colspan="6" class="text-center text-secondary py-5">Data antrean belum tersedia.</td></tr><?php else:foreach($data as $r):?><tr><td class="ps-3 fw-semibold"><?=aman_html($r['kode_poli'].'-'.str_pad((string)$r['nomor_antrean'],3,'0',STR_PAD_LEFT));?></td><td><?=aman_html($r['nama_pasien']);?></td><td><?=aman_html($r['kode_poli'].' - '.$r['nama_poli']);?></td><td><?=aman_html(date('d/m/Y',strtotime($r['tanggal_antrean'])));?></td><td><span class="badge text-bg-<?= $r['status_antrean']==='menunggu'?'warning':($r['status_antrean']==='dipanggil'?'primary':($r['status_antrean']==='selesai'?'success':'secondary'));?>"><?=aman_html(ucfirst($r['status_antrean']));?></span></td><td class="text-end pe-3"><div class="d-inline-flex gap-2"><a class="btn btn-sm btn-outline-success" href="<?=aman_html(url_aplikasi('admin/formulir-antrean.php?id_antrean='.(int)$r['id_antrean']));?>">Edit</a><form id="hapus-<?= (int)$r['id_antrean'];?>" method="post" action="<?=aman_html(url_aplikasi('proses/proses_antrean.php'));?>"><input type="hidden" name="token_csrf" value="<?=aman_html(token_csrf());?>"><input type="hidden" name="aksi" value="hapus"><input type="hidden" name="id_antrean" value="<?= (int)$r['id_antrean'];?>"><button type="button" class="btn btn-sm btn-outline-danger hapus" data-bs-toggle="modal" data-bs-target="#modalHapus" data-form="hapus-<?= (int)$r['id_antrean'];?>">Hapus</button></form></div></td></tr><?php endforeach;endif;?></tbody></table></div><?php if($total_halaman>1):?><nav class="p-3"><ul class="pagination justify-content-end mb-0"><?php for($i=1;$i<=$total_halaman;$i++):?><li class="page-item <?=$i===$halaman?'active':'';?>"><a class="page-link" href="<?=aman_html(url_antrean($i,$cari,$status));?>"><?=$i;?></a></li><?php endfor;?></ul></nav><?php endif;?></section></main></div>
<div class="modal fade" id="modalHapus" tabindex="-1"><div class="modal-dialog modal-dialog-centered"><div class="modal-content border-0"><div class="modal-header bg-success text-white"><h2 class="modal-title fs-5">Konfirmasi Hapus</h2><button class="btn-close btn-close-white" data-bs-dismiss="modal"></button></div><div class="modal-body">Apakah Anda yakin ingin menghapus data antrean ini?</div><div class="modal-footer"><button class="btn btn-outline-secondary" data-bs-dismiss="modal">Batal</button><button class="btn btn-success" id="yaHapus">Ya, Hapus</button></div></div></div></div><script>let f='';document.querySelectorAll('.hapus').forEach(x=>x.onclick=()=>f=x.dataset.form);document.getElementById('yaHapus').onclick=()=>document.getElementById(f).submit();</script><?php require_once __DIR__.'/../includes/kaki.php';?>
